# Let me redo the region analysis more carefully

def parse_grid(text):
    lines = text.strip().split('\n')
    return [[int(x) for x in line.split()] for line in lines]

def find_all_horizontal_rows(grid):
    return [i for i, row in enumerate(grid) if len(set(row)) == 1]

def find_all_vertical_cols(grid):
    if not grid:
        return []
    return [j for j in range(len(grid[0])) if len(set(grid[i][j] for i in range(len(grid)))) == 1]

# Define demos
demos_info = {
    "1": {
        "text": demos_text["1"],
        "output": [[2,1,1,1,1],[1,1,1,1,1]],
        "h_lines": [4],
        "v_cols": [2, 5, 8, 11]
    },
    "2": {
        "text": demos_text["2"],
        "output": [[1,9],[9,9],[9,1]],
        "h_lines": [4, 9],
        "v_cols": [3]
    },
    "3": {
        "text": demos_text["3"],
        "output": [[6,6,6,6],[6,6,6,1],[6,6,6,6]],
        "h_lines": [5, 11],
        "v_cols": [4, 9, 14]
    },
    "4": {
        "text": demos_text["4"],
        "output": [[1,6,6],[1,6,1]],
        "h_lines": [5],
        "v_cols": [4, 9]
    },
    "5": {
        "text": demos_text["5"],
        "output": [[1,1,1,1],[1,1,1,1],[5,1,1,1]],
        "h_lines": [4, 9],
        "v_cols": [3, 7, 11]
    }
}

for name in ["1", "2", "3", "4", "5"]:
    info = demos_info[name]
    grid = parse_grid(info["text"])

    h_lines = info["h_lines"]
    v_cols = info["v_cols"]
    print(f"\n=== Demo {name} ===")
    print(f"H lines: {h_lines}, V cols: {v_cols}")

    h_bounds = [-1] + h_lines + [len(grid)]
    v_bounds = [-1] + v_cols + [len(grid[0])]

    # Get line colors
    if h_lines:
        h_line_color = grid[h_lines[0]][0]
    else:
        h_line_color = None

    if v_cols:
        v_line_color = grid[0][v_cols[0]]
    else:
        v_line_color = None

    print(f"Line colors: H={h_line_color}, V={v_line_color}")

    # Analyze each region
    for r in range(len(h_lines) + 1):
        for c in range(len(v_cols) + 1):
            start_r, end_r = h_bounds[r] + 1, h_bounds[r+1]
            start_c, end_c = v_bounds[c] + 1, v_bounds[c+1]

            region_pixels = set()
            for i in range(start_r, end_r):
                for j in range(start_c, end_c):
                    region_pixels.add(grid[i][j])

            # Special pixel = not background, not h-line, not v-line
            # Background is the most common non-line pixel (need to determine this)
            all_pixels = set()
            for row in grid:
                for pixel in row:
                    all_pixels.add(pixel)

            # Assume background is the most frequent non-line pixel in the whole grid
            from collections import Counter
            pixel_counts = Counter(grid[i][j] for i in range(len(grid)) for j in range(len(grid[0])))
            background = max(pixel_counts.keys(), key=lambda k: pixel_counts[k])

            # Is pixel special = is it special AND is this the special position
            h_color_set = set(h_line_color) if h_line_color else set()
            v_color_set = set(v_line_color) if v_line_color else set()

            special_pixel_found = any(p != background and p not in h_color_set and p not in v_color_set for p in region_pixels)
            print(f"Region ({r},{c}): cols={start_c}-{end_c}, H={start_r}-{end_r}, pixels={sorted(region_pixels)}, special={special_pixel_found}")

